package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.widget.*;import androidx.media3.exoplayer.ExoPlayer;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class RestorationTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private File source;private Uri uri,target;private String stamp;private AudioRestorationActivity screen;private final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
 interface Check{boolean ready()throws Exception;}
 private Object field(Object target,String name)throws Exception{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 private void call(String method,Class<?>[] types,Object...args){try{java.lang.reflect.Method m=AudioRestorationActivity.class.getDeclaredMethod(method,types);m.setAccessible(true);m.invoke(screen,args);}catch(Exception e){throw new RuntimeException(e);}}
 private void waitFor(Check check)throws Exception{for(int i=0;i<600;i++){boolean[] done={false};ins.runOnMainSync(()->{try{done[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(done[0])return;Thread.sleep(50);}fail("Restoration timed out");}
 private void shell(String s)throws Exception{try(ParcelFileDescriptor fd=ins.getUiAutomation().executeShellCommand(s);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}}
 @Before public void before()throws Exception{source=AudioTestFixtures.tone(c,15000);uri=Uri.fromFile(source);stamp=AudioChapterStore.stamp(c,uri);Uri tree=DocumentsContract.buildTreeDocumentUri(c.getPackageName()+".test.batchdocs","root");Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,"root");target=DocumentsContract.createDocument(c.getContentResolver(),parent,"audio/mpeg","restoration-"+UUID.randomUUID()+".mp3");}
 @After public void after()throws Exception{release.countDown();shell("input keyevent 224");shell("wm dismiss-keyguard");ins.runOnMainSync(()->{if(screen!=null)screen.finish();c.stopService(new Intent(c,ChapterExportService.class));});waitFor(()->{java.lang.reflect.Field f=ChapterExportService.class.getDeclaredField("live");f.setAccessible(true);return f.get(null)==null;});ChapterExportService.converter=ChapterExportTask::run;source.delete();try{DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}ins.waitForIdleSync();}
 private ChapterExportJob job(int profile){return new ChapterExportJob(UUID.randomUUID().toString(),uri,target,stamp,"Restaurada",0,15000,15000,192,"",profile);}
 @Test public void oldJobsRemainUntreatedAndProfileSurvivesNotification()throws Exception{ChapterExportJob restored=job(2),read=ChapterExportJob.parse(restored.json().toString());assertEquals(2,read.restorationProfile);assertEquals(2,read.screen(c).getIntExtra("restoration_profile",-1));org.json.JSONObject old=restored.json();old.remove("restoration_profile");assertEquals(0,ChapterExportJob.parse(old.toString()).restorationProfile);assertFalse(job(9).valid());}
 @Test public void realMp3PreviewAndFullCopyNeverChangeOriginal()throws Exception{byte[] original=java.nio.file.Files.readAllBytes(source.toPath());File out=File.createTempFile("restoration-check-",".mp3",c.getCacheDir());try{ChapterMp3Exporter.convert(MediaInput.file(source),out,192,2000,5000,1,new ChapterMp3Exporter.Control(){public void check(){}public void progress(long a,long b){}});assertTrue(new ChapterExportTest().decodedRms(out,3000)>100);ChapterExportTask.run(c,job(2),c.getContentResolver().openAssetFileDescriptor(target,"rw"),new ChapterExportTask.Control(){public void check(){}public void stage(String m){}public void progress(long a,long b){}});try(InputStream in=c.getContentResolver().openInputStream(target);OutputStream sink=new FileOutputStream(out)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)sink.write(b,0,n);}assertTrue(new ChapterExportTest().decodedRms(out,15000)>100);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}finally{out.delete();}}
 private void open()throws Exception{screen=(AudioRestorationActivity)ins.startActivitySync(new Intent(c,AudioRestorationActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->screen.hasWindowFocus());ins.runOnMainSync(()->call("load",new Class<?>[]{Uri.class},uri));waitFor(()->field(screen,"source")!=null&&!(Boolean)field(screen,"busy"));}
 @Test public void previewNeverAutoplaysAndStopsWhenLeaving()throws Exception{open();ins.runOnMainSync(()->{try{assertNull(field(screen,"player"));((Button)field(screen,"prepare")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(screen,"preview")!=null&&!(Boolean)field(screen,"busy"));ins.runOnMainSync(()->{try{assertNull(field(screen,"player"));((Button)field(screen,"treated")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(screen,"player")!=null&&((ExoPlayer)field(screen,"player")).isPlaying());shell("input keyevent 3");waitFor(()->field(screen,"player")==null);}
 @Test public void changingPreviewInvalidatesOldOutputAndUiIsReadable()throws Exception{open();ins.runOnMainSync(()->{try{((Button)field(screen,"prepare")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->field(screen,"preview")!=null);File old=(File)field(screen,"preview");ins.waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap image=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"restoration.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}ins.runOnMainSync(()->call("invalidatePreview",new Class<?>[0]));assertFalse(old.exists());assertNull(field(screen,"preview"));}
 @Test public void foregroundRestorationCompletesWithScreenOff()throws Exception{open();byte[] original=java.nio.file.Files.readAllBytes(source.toPath());ChapterExportService.converter=(context,job,fd,control)->{entered.countDown();try{if(!release.await(20,TimeUnit.SECONDS))throw new IOException("Gate timeout");}catch(InterruptedException e){throw new InterruptedIOException();}ChapterExportTask.run(context,job,fd,control);};ins.runOnMainSync(()->{try{assertTrue(ChapterExportService.start(screen,job(1)));}catch(IOException e){throw new RuntimeException(e);}});assertTrue(entered.await(10,TimeUnit.SECONDS));shell("input keyevent 3");shell("input keyevent 223");assertTrue(ChapterExportService.state(c).running);release.countDown();waitFor(()->!ChapterExportService.state(c).running);assertEquals(ChapterExportService.state(c).message,"done",ChapterExportService.state(c).phase);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}
 @Test public void cancellingRestorationAndAliasedDestinationPreserveSource()throws Exception{File out=File.createTempFile("restoration-cancel-",".mp3",c.getCacheDir());byte[] original=java.nio.file.Files.readAllBytes(source.toPath());int[] calls={0};try{try{ChapterMp3Exporter.convert(MediaInput.file(source),out,192,0,15000,1,new ChapterMp3Exporter.Control(){public void check()throws IOException{if(++calls[0]>5)throw new InterruptedIOException();}public void progress(long a,long b){}});fail();}catch(InterruptedIOException expected){}try{ChapterExportTask.run(c,job(1),c.getContentResolver().openAssetFileDescriptor(uri,"rw"),new ChapterExportTask.Control(){public void check(){}public void stage(String s){}public void progress(long a,long b){}});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("novo arquivo vazio"));}assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}finally{out.delete();}}
}
